+using System.ComponentModel;
+using System.Text;
+using System.Text.Json;
+using Microsoft.Extensions.AI;
+
+namespace ResearchAgent;
+
+/// <summary>
+/// Tools available to the research agent for web search and note-taking.
+/// </summary>
+public sealed class ResearchTools
+{
+    private readonly HttpClient _httpClient;
+    private readonly List<NoteEntry> _notes = [];
+
+    public ResearchTools(HttpClient httpClient)
+    {
+        _httpClient = httpClient;
+    }
+
+    [Description("Searches the web for the given query and returns a list of result titles, snippets, and URLs. Use this to find information about a topic.")]
+    public async Task<IReadOnlyList<SearchResult>> SearchWebAsync(
+        [Description("The search query string")] string query,
+        [Description("Maximum number of results to return (1-10)")] int maxResults = 5,
+        CancellationToken cancellationToken = default)
+    {
+        maxResults = Math.Clamp(maxResults, 1, 10);
+
+        // Uses DuckDuckGo Lite (HTML), which doesn't require an API key.
+        var encodedQuery = Uri.EscapeDataString(query);
+        var url = $"https://lite.duckduckgo.com/lite/?q={encodedQuery}";
+
+        using var request = new HttpRequestMessage(HttpMethod.Get, url);
+        request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");
+
+        using var response = await _httpClient.SendAsync(request, cancellationToken);
+        response.EnsureSuccessStatusCode();
+
+        var html = await response.Content.ReadAsStringAsync(cancellationToken);
+        var results = ParseDuckDuckGoLiteResults(html, maxResults);
+
+        return results.Count > 0
+            ? results
+            : [new SearchResult($"No results found for '{query}'", "", "")];
+    }
+
+    [Description("Saves a research note with a title and content. Use this to record key findings during research.")]
+    public string SaveNote(
+        [Description("A short descriptive title for the note")] string title,
+        [Description("The content of the note — key facts, quotes, or observations")] string content)
+    {
+        _notes.Add(new NoteEntry(title, content, DateTime.UtcNow));
+        return $"Note saved: \"{title}\" ({_notes.Count} total notes)";
+    }
+
+    [Description("Returns all saved research notes so far. Use this to review collected findings before writing a summary.")]
+    public IReadOnlyList<NoteEntry> GetNotes()
+    {
+        return _notes.AsReadOnly();
+    }
+
+    /// <summary>
+    /// Parses search result rows from DuckDuckGo Lite HTML output.
+    /// The Lite page renders results as table rows with specific CSS classes.
+    /// </summary>
+    private static List<SearchResult> ParseDuckDuckGoLiteResults(string html, int max)
+    {
+        var results = new List<SearchResult>();
+
+        // DuckDuckGo Lite renders results in <a class="result-link"> tags followed by
+        // <td class="result-snippet"> cells. We parse these with simple string scanning
+        // to avoid adding an HTML parser dependency.
+        var position = 0;
+        while (results.Count < max)
+        {
+            var linkStart = html.IndexOf("class=\"result-link\"", position, StringComparison.Ordinal);
+            if (linkStart < 0) break;
+
+            var hrefStart = html.LastIndexOf("href=\"", linkStart, Math.Min(linkStart, 200), StringComparison.Ordinal);
+            string resultUrl = "";
+            if (hrefStart >= 0)
+            {
+                hrefStart += 6;
+                var hrefEnd = html.IndexOf('"', hrefStart);
+                if (hrefEnd > hrefStart)
+                    resultUrl = html[hrefStart..hrefEnd];
+            }
+
+            // Extract link text as title
+            var tagClose = html.IndexOf('>', linkStart);
+            var linkEnd = html.IndexOf("</a>", tagClose, StringComparison.Ordinal);
+            var title = tagClose >= 0 && linkEnd > tagClose
+                ? StripHtml(html[(tagClose + 1)..linkEnd]).Trim()
+                : "";
+
+            // Look for the snippet in the next result-snippet cell
+            var snippetStart = html.IndexOf("class=\"result-snippet\"", linkEnd > 0 ? linkEnd : linkStart + 1, StringComparison.Ordinal);
+            string snippet = "";
+            if (snippetStart >= 0)
+            {
+                var snippetTagClose = html.IndexOf('>', snippetStart);
+                var snippetEnd = html.IndexOf("</td>", snippetTagClose, StringComparison.Ordinal);
+                if (snippetTagClose >= 0 && snippetEnd > snippetTagClose)
+                    snippet = StripHtml(html[(snippetTagClose + 1)..snippetEnd]).Trim();
+            }
+
+            if (!string.IsNullOrWhiteSpace(title))
+                results.Add(new SearchResult(title, snippet, resultUrl));
+
+            position = linkEnd > 0 ? linkEnd : linkStart + 1;
+        }
+
+        return results;
+    }
+
+    private static string StripHtml(string html)
+    {
+        var sb = new StringBuilder(html.Length);
+        var inTag = false;
+        foreach (var c in html)
+        {
+            if (c == '<') { inTag = true; continue; }
+            if (c == '>') { inTag = false; continue; }
+            if (!inTag) sb.Append(c);
+        }
+        return System.Net.WebUtility.HtmlDecode(sb.ToString());
+    }
+}
+
