using System.ClientModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

// --- Configuration -----------------------------------------------------------
// API key from environment variable or user-secrets; never hardcoded.
var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in user-secrets.");

// Pin to a specific model version to reduce behavioral drift.
var modelId = builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18";

// --- Services ----------------------------------------------------------------
builder.Services.AddHttpClient<ResearchTools>();

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(new ApiKeyCredential(apiKey))));

builder.Services.AddSingleton<ResearchTools>(sp =>
    new ResearchTools(sp.GetRequiredService<IHttpClientFactory>().CreateClient(nameof(ResearchTools))));

using var host = builder.Build();

// --- Build the agent ---------------------------------------------------------
var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var agentTools = new List<AITool>
{
    AIFunctionFactory.Create(tools.SearchWebAsync),
    AIFunctionFactory.Create(tools.SaveNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

const string instructions = """
    You are a research assistant. Your job is to thoroughly research a topic the user provides.

    Workflow:
    1. Break the topic into 2-3 search queries that cover different angles.
    2. For each query, call SearchWebAsync to find relevant information.
    3. As you discover key facts, call SaveNote to record them with clear titles.
    4. After completing your research, call GetNotes to review everything you collected.
    5. Write a well-structured summary that synthesizes your notes into a coherent report.
       Include the sources (URLs) where you found the information.

    Guidelines:
    - Be thorough but concise — aim for a summary of 300-500 words.
    - Cite your sources inline using [Source Title](URL) format.
    - If search results are sparse, note gaps in available information.
    - Always save at least 3 notes before summarizing.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches topics using web search and note-taking tools",
    tools: agentTools);

// --- Run the agent -----------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent                 ║");
Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching... (the agent will search the web and take notes)");
    Console.ResetColor();
    Console.WriteLine();

    try
    {
        using var session = await agent.CreateSessionAsync();

        await foreach (var update in agent.RunStreamingAsync(
            $"Please research the following topic: {topic}",
            session,
            new ChatClientAgentRunOptions(new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
            })))
        {
            if (update.Role == ChatRole.Assistant)
            {
                Console.Write(update.Text);
            }
        }

        Console.WriteLine();
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
        Console.WriteLine();
    }
}

Console.WriteLine("Goodbye!");

