2. using System.Text;
3. using System.Text.Json;
4. using Microsoft.Extensions.AI;
5. 
6. namespace ResearchAgent;
7. 
8. /// <summary>
9. /// Tools available to the research agent for web search and note-taking.
10. /// </summary>
11. public sealed class ResearchTools
12. {
13.     private readonly HttpClient _httpClient;
14.     private readonly List<NoteEntry> _notes = [];
15. 
16.     public ResearchTools(HttpClient httpClient)
17.     {
18.         _httpClient = httpClient;
19.     }
20. 
21.     [Description("Searches the web for the given query and returns a list of result titles, snippets, and URLs. Use this to find information about a topic.")]
22.     public async Task<IReadOnlyList<SearchResult>> SearchWebAsync(
23.         [Description("The search query string")] string query,
24.         [Description("Maximum number of results to return (1-10)")] int maxResults = 5,
25.         CancellationToken cancellationToken = default)
26.     {
27.         maxResults = Math.Clamp(maxResults, 1, 10);
28. 
29.         // Uses DuckDuckGo Lite (HTML), which doesn't require an API key.
30.         var encodedQuery = Uri.EscapeDataString(query);
31.         var url = $"https://lite.duckduckgo.com/lite/?q={encodedQuery}";
32. 
33.         using var request = new HttpRequestMessage(HttpMethod.Get, url);
34.         request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");
35. 
36.         using var response = await _httpClient.SendAsync(request, cancellationToken);
37.         response.EnsureSuccessStatusCode();
38. 
39.         var html = await response.Content.ReadAsStringAsync(cancellationToken);
40.         var results = ParseDuckDuckGoLiteResults(html, maxResults);
41. 
42.         return results.Count > 0
43.             ? results
44.             : [new SearchResult($"No results found for '{query}'", "", "")];
45.     }
46. 
47.     [Description("Saves a research note with a title and content. Use this to record key findings during research.")]
